WITH lignes AS (
  SELECT v.id, v.jour, v.client_id, p.nom, p.categorie, v.quantite * p.prix AS montant
  FROM ventes AS v JOIN produits AS p ON p.id = v.produit_id
)
SELECT client_id, jour, montant, SUM(montant) OVER (ORDER BY jour, id) AS cumul_client FROM lignes WHERE client_id IS NOT NULL ORDER BY client_id, jour, id;

WITH par_jour AS (
  SELECT v.jour, SUM(v.quantite * p.prix) AS ca
  FROM ventes AS v JOIN produits AS p ON p.id = v.produit_id
  GROUP BY v.jour
)
SELECT jour, ca, SUM(ca) OVER (ORDER BY jour) AS cumul FROM par_jour ORDER BY jour;
